# 
# ---- ANOVA Example: Executive Function in Clinical Groups ----------------------
# 
# **Context:**
# 
# The outcome is the Trail Making Test part B (TMT-B): the patient connects
# numbers and letters in alternating order as quickly as possible. The score is
# the time in seconds, so higher means worse. The data are simulated.
# 
# **You will see:**
# 
# 1. A t-test and an ANOVA as linear regressions
# 2. How coding a factor changes what the coefficients mean
# 3. Post-hoc comparisons and assumption checks
# 4. Repeated measures with `aov()` and `lmer()`
# 
# If you do not have these packages yet, install them once:
# 
# install.packages(c("car", "rstatix", "lme4", "lmerTest"))

# 
# ---- The data: three diagnostic groups -----------------------------------------
# 
groups <- read.csv("data/tmt-groups.csv")
head(groups)

# the first level is the reference group, so put controls first
groups$diagnosis <- factor(groups$diagnosis, levels = c("Control", "MCI", "AD"))

tapply(groups$tmt_b, groups$diagnosis, mean)
boxplot(tmt_b ~ diagnosis, data = groups)

# 
# ---- Part 1: Do MCI patients differ from controls? -----------------------------
# 
# The t-test and `lm()` give the same t (with the sign flipped) and the same p.
# The slope is the difference between the two group means.
# 
two_groups <- droplevels(subset(groups, diagnosis != "AD"))

t.test(tmt_b ~ diagnosis, data = two_groups, var.equal = TRUE)
summary(lm(tmt_b ~ diagnosis, data = two_groups))

# 
# ---- Part 2: Do the three groups differ? ---------------------------------------
# 
# ---- Step 1: Fit the model -----------------------------------------------------
# 
# 
lm_mod <- lm(tmt_b ~ diagnosis, data = groups)
summary(lm_mod)
anova(lm_mod)

# 
# ---- Step 2: Change the coding -------------------------------------------------
# 
# With deviation coding the fit is the same, but the intercept becomes the general
# mean, and each coefficient is a group's difference from it. R labels them by
# level number: `diagnosis1` is controls and `diagnosis2` is MCI. AD gets no row of
# its own.
# 
lm_mod_sum <- lm(tmt_b ~ diagnosis, contrasts = list(diagnosis = "contr.sum"),
                 data = groups)
summary(lm_mod_sum)
mean(groups$tmt_b)

# 
# ---- Step 3: The usual ANOVA, and which groups differ --------------------------
# 
# `aov()` fits the same model. With a single factor, types I, II and III
# give the same F for `diagnosis`. 
# 
aov_mod <- aov(tmt_b ~ diagnosis, data = groups)
summary(aov_mod)
car::Anova(aov_mod, type = 2)
car::Anova(aov_mod, type = 3)
TukeyHSD(aov_mod)

# 
# ---- Step 4: Diagnostics -------------------------------------------------------
# 
par(mfrow = c(2, 2))
plot(aov_mod)
dev.off()

# 
car::leveneTest(aov_mod) # equality of variances across groups

# 
# ---- Part 3: Do stroke patients improve with rehabilitation? -------------------
# 
# The same 40 patients do the TMT-B at three visits, so the file has one row per
# patient per visit. Some patients are faster than others at every visit, and a
# repeated-measures model separates that from the change over time.
# 
rehab <- read.csv("data/tmt-rehab.csv")
head(rehab)

rehab$patient <- factor(rehab$patient)
rehab$visit   <- factor(rehab$visit, levels = c("Baseline", "Post", "FollowUp"))

tapply(rehab$tmt_b, rehab$visit, mean)
boxplot(tmt_b ~ visit, data = rehab)

# 
# ---- Step 1: Repeated-measures ANOVA -------------------------------------------
# 
# Ignoring the repeated measures leaves the differences between patients in the
# error term, which gives a much weaker F. `Error(patient/visit)` removes them.
# 
summary(aov(tmt_b ~ visit, data = rehab))                         # wrong: treats visits as independent
summary(aov(tmt_b ~ visit + Error(patient/visit), data = rehab))  # right

# same analysis, with Mauchly's test of sphericity
rstatix::anova_test(data = rehab, dv = tmt_b, wid = patient, within = visit)

# 
# ---- Step 2: Mixed-effects model -----------------------------------------------
# 
# `(1 | patient)` gives each patient their own baseline level. Each `visit`
# coefficient is the change from baseline, in seconds.
# 
library(lme4)
library(lmerTest) # load this to get p-values in lmer

lmer_mod <- lmer(tmt_b ~ visit + (1 | patient), data = rehab)
summary(lmer_mod)

# proportion of the remaining variance due to differences between patients
vars <- as.data.frame(VarCorr(lmer_mod))
vars$vcov[1] / (vars$vcov[1] + vars$vcov[2])

plot(lmer_mod)              # residuals vs fitted
qqnorm(residuals(lmer_mod)) # normality of residuals
